internal final class NDXUSCImportUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField dfField1;
    DialogField dfField2;

}

Method.Source:
private void modifyDialogFields()
{
    // Disable field2 based on some condition
    dfField1.enabled(false);
}

public void postBuild()
{
    super();
    dfField1 = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(NDXUSCImportContract, parmVatNum));
    dfField2 = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(NDXUSCImportContract, parmAll));
    this.modifyDialogFields();
}
